{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Codeine, the closest structural analogue, has an absolute oral bioavailability of 40% in postoperative patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Codeine sulfate in healthy subjects shows an oral bioavailability of 80.5%, strongly supporting high oral bioavailability for the codeine-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ethylmorphine, a close O-alkyl analogue, had an estimated absolute bioavailability of 28%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Diacetylmorphine, a more derivatized morphinan, shows oral bioavailability of 45.6–64.5%, supporting the pattern of high oral availability in this family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Morphine, the demethylated analogue, showed mean absolute oral bioavailability of 29.2% in fasted healthy volunteers, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a more distant morphinan alkaloid, has an absolute oral bioavailability of 30%, further supporting that morphinan-type molecules generally exceed 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a codeine-like morphinan alkaloid. Direct oral bioavailability measurements from codeine (40–100%), codeine sulfate (80.5%), ethylmorphine (28–74%), diacetylmorphine (45.6–64.5%), morphine (20–45%), and noscapine (30%) all meet or exceed the 20% threshold. The closest analogue, codeine, has consistently high oral bioavailability, and no experimental evidence supports low F. Therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "Morgan similarity to the closest analogue is moderate (0.41), so the quantitative F value may differ, though the threshold is low.",
    "First-pass metabolic stability of this specific N-methyl morphinan is not directly measured, but all close analogues still exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

